// Scratch helper (not part of the build): syntax-check .vue SFCs (both script
// blocks + template) and .js modules without a dev server. Safe to delete.
//
//   node tmp/channel-creator-check.cjs <file...>
//
// Run it inside a container that has node + the client's node_modules.
const fs = require('fs')
const p = require('/home/codx-junior/codx-junior/client/node_modules/@vue/compiler-sfc')
const babel = require('/home/codx-junior/codx-junior/client/node_modules/@babel/parser')

const files = process.argv.slice(2)
let failed = false

function parseJs(source, filename, label) {
  babel.parse(source, { sourceType: 'module', plugins: ['optionalChaining'] })
  void filename
  void label
}

for (const f of files) {
  try {
    const src = fs.readFileSync(f, 'utf8')
    if (f.endsWith('.vue')) {
      const { descriptor, errors } = p.parse(src)
      if (errors.length) throw new Error(JSON.stringify(errors, null, 1))
      if (descriptor.template) {
        const t = p.compileTemplate({
          source: descriptor.template.content,
          filename: f,
          id: 'check'
        })
        if (t.errors.length) throw new Error(JSON.stringify(t.errors, null, 1))
      }
      if (descriptor.script) parseJs(descriptor.script.content, f, 'script')
      if (descriptor.scriptSetup) parseJs(descriptor.scriptSetup.content, f, 'script setup')
    } else {
      parseJs(src, f, 'module')
    }
    console.log('OK   ' + f)
  } catch (e) {
    failed = true
    console.log('FAIL ' + f + '\n' + (e.message || e))
  }
}

process.exit(failed ? 1 : 0)

